def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]
    recent = history[-10:]
    opp_c = sum(1 for a, b in recent if b == 'C')
    total_opp_c = sum(1 for a, b in history if b == 'C')
    total_opp_d = n - total_opp_c

    if total_opp_d == 0:
        return 'C'
    if total_opp_c == 0:
        return 'D'

    if opp_last == 'D':
        if opp_c >= 9:
            return 'C'
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    return 'C'
